SELECT f.goods_id FROM t_goods_favorite f
INNER JOIN t_goods g ON f.goods_id = g.id AND g.deleted = 0
WHERE f.user_id = #{userId} AND f.deleted = 0 AND g.status = #{status}
ORDER BY f.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM t_goods_favorite f
INNER JOIN t_goods g ON f.goods_id = g.id AND g.deleted = 0
WHERE f.user_id = #{userId} AND f.deleted = 0 AND g.status = #{status}
